CREATE TABLE composer(cid INTEGER PRIMARY KEY, cname TEXT); CREATE TABLE album(aid INTEGER PRIMARY KEY, aname TEXT); CREATE TABLE track(tid INTEGER PRIMARY KEY, cid INTEGER REFERENCES composer, aid INTEGER REFERENCES album, title TEXT); CREATE INDEX track_i1 ON track(cid); CREATE INDEX track_i2 ON track(aid); INSERT INTO composer VALUES(1, 'W. A. Mozart'),(2, 'Beethoven'),(3, 'Thomas Tallis'),(4, 'Joseph Hayden'),(5, 'Thomas Weelkes'),(6, 'J. S. Bach'),(7, 'Orlando Gibbons'),(8, 'Josquin des Prés'),(9, 'Byrd'),(10, 'Francis Poulenc'),(11, 'Mendelsshon'),(12, 'Zoltán Kodály'),(13, 'Handel'); INSERT INTO album VALUES(100, 'Kodály: Missa Brevis'),(101, 'Messiah'),(102, 'Missa Brevis in D-, K.65'),(103, 'The complete English anthems'),(104, 'Mass in B Minor, BWV 232'); INSERT INTO track VALUES(10005, 12, 100, 'Sanctus'),(10007, 12, 100, 'Agnus Dei'),(10115, 13, 101, 'Surely He Hath Borne Our Griefs'),(10129, 13, 101, 'Since By Man Came Death'),(10206, 1, 102, 'Agnus Dei'),(10301, 3, 103, 'If Ye Love Me'),(10402, 6, 104, 'Domine Deus'),(10403, 6, 104, 'Qui tollis');